('kurma-ajwa-madinah', 'Kurma Ajwa Aliyah Madinah', 'kurma', 'Madinah Al-Munawwarah', 'Kurma Nabi dari kebun Aliyah Madinah dengan tekstur empuk, kerutan rapat, tidak terlalu manis, dan berkhasiat tinggi.', 'best-seller', 'Best Seller', '/images/ajwa.webp', 0, array['100% Asli Madinah Bersertifikat', 'Tekstur Daging Lembut & Bebas Kutu', 'Disimpan di Ruangan Sejuk & Higienis']::text[], 4.95, 348, 0),
('kurma-sukari-qassim', 'Kurma Sukari Rutob Al-Qassim', 'kurma', 'Al-Qassim, Arab Saudi', 'Dikenal sebagai kurma ratu, berdaging basah (rutob) karamel yang meleleh di mulut dengan rasa manis lembut alami.', 'favorit', 'Favorit Jamaah', '/images/sukkari.webp', 0, array['Rasa Manis Lembut Seperti Madu Karamel', 'Kualitas Segar & Terjaga', 'Sangat Disukai Orang Tua & Anak']::text[], 4.9, 289, 1),
('kurma-khalas-saad', 'Kurma Khalas Saad Premium', 'kurma', 'Uni Emirat Arab', 'Kurma khalas pilihan dengan tekstur kenyal legit, aroma khas karamel stabil, kemasan rapi masa kedaluwarsa panjang 2027.', 'favorit', 'Exp. 2027', '/images/khalas.webp', 0, array['Daging Tebal & Rasa Manis Pas', 'Higienis Press Pack Vacuum', 'Expired Panjang Tahun 2027']::text[], 4.8, 195, 2),
('kurma-tunis-madu', 'Kurma Tunis Madu & Bertangkai', 'kurma', 'Tunisia / Algeria', 'Kurma Deglet Noor bertangkai dengan tekstur kenyal madu, sedikit renyah, dan rasa manis sedang yang tidak enek.', 'premium', 'Tekstur Madu', '/images/tunis.webp', 0, array['Bentuk Lonjong Ramping Transparan Madu', 'Tekstur Renyah Legit Segar', 'Cocok untuk Sajian Tamu Eksklusif']::text[], 4.85, 164, 3),
('kurma-mesir-akram', 'Kurma Mesir (Akram & Golden River)', 'kurma', 'Lembah Nil, Mesir', 'Kurma semi-kering ekonomis berserat padat legit, sangat cocok untuk konsumsi harian, takjil, sedekah, dan suvenir massal.', 'terbatas', 'Super Hemat', '/images/mesir.webp', 1, array['Paling Ekonomis untuk Jamaah & Sedekah', 'Tekstur Daging Padat & Kenyal', 'Tersedia Eceran Maupun Kartonan']::text[], 4.75, 210, 4),
('kurma-ruthob-libya', 'Kurma Ruthob Libya Segar', 'kurma', 'Libya / Timur Tengah', 'Kurma muda segar krenyes-krenyes dengan rasa manis kesat alami yang menyegarkan, kaya enzim dan serat hidup.', 'favorit', 'Fresh Krenyes', '/images/ruthob.webp', 0, array['Panen Segar Krenyes Renyah', 'Sensasi Dingin Menyegarkan', 'Kaya Nutrisi Kesuburan & ASI Booster']::text[], 4.9, 142, 5),
('kurma-bam-diamond', 'Kurma Bam / Anggur (Diamond & Akram)', 'kurma', 'Bam, Iran', 'Kurma basah hitam pekat berdaging super lembut lumer seperti selai anggur dengan kelembapan tinggi, disimpan dingin.', 'premium', 'Lumer Lembut', '/images/bam.webp', 1, array['Daging Hitam Pekat Lumer di Lidah', 'Kadar Air Tinggi Lembut Alami', 'Disimpan Beku/Dingin 4°C']::text[], 4.8, 118, 6),
('kurma-palmfruit', 'Kurma Palm Fruit Tunisia Box', 'kurma', 'Tozeur, Tunisia', 'Kurma bertangkai kemasan box eksklusif Palm Fruit asal Tunisia, higienis dan elegan dengan rasa manis madu alami.', 'premium', 'Impor Tunisia', '/images/palmfruit.webp', 0, array['Merk Palm Fruit Orisinal Bertangkai', 'Box Segel Rapi Elegan', 'Cocok untuk Parsel & Hantaran']::text[], 4.88, 97, 7),
('kurma-medjool-jumbo', 'Kurma Medjool Natural Jumbo', 'kurma', 'Jericho / California', 'Ukuran king size jumbo istimewa dengan daging super tebal, lembut kenyal, dan serat halus kaya antioksidan serta potasium.', 'premium', 'Kualitas VIP', '/images/medjool.webp', 0, array['Ukuran Jumbo Raja Kurma', 'Daging Sangat Tebal & Lembut', 'Kualitas Super Premium Eksekutif']::text[], 4.95, 167, 8),
('kacang-pistachio', 'Kacang Fustuk / Pistachio Panggang', 'kismis-kacang', 'Iran / California', 'Kacang fustuk pilihan kulit terbuka alami, dipanggang renyah dengan rasa gurih asin pas khas Timur Tengah.', 'best-seller', 'Gurih Renyah', '/images/pistachio.webp', 0, array['Kulit Mudah Dikupas Alami', 'Rasa Gurih Asin Sedap Tanpa Minyak', 'Kaya Lemak Sehat & Protein']::text[], 4.9, 224, 9),
('kacang-almond-selma', 'Kacang Almond Selma & Cangkang', 'kismis-kacang', 'California', 'Kacang almond panggang rasa susu (milk flavor), renyah gurih alami kaya vitamin E dan kalsium.', 'favorit', 'Panggang Susu', '/images/almond.webp', 0, array['Panggang Oven Harum Rasa Susu', 'Tersedia Kupas Bersih & Kulit Cangkang', 'Kaya Antioksidan & Vitamin E']::text[], 4.88, 153, 10),
('kacang-arab-humush', 'Kacang Arab Humush Panggang', 'kismis-kacang', 'Turki / Mesir', 'Kacang arab gurih empuk tidak keras, dipanggang bersih dengan rasa renyah asin seimbang khas oleh-oleh haji umroh.', 'favorit', 'Camilan Haji', '/images/kacang-arab.webp', 0, array['Renyah Gurih Tidak Keras di Gigi', 'Tradisi Oleh-Oleh Haji Wajib', 'Kemasan Tebal Higienis']::text[], 4.8, 275, 11),
('kacang-mete-wonogiri', 'Kacang Mete Super Wonogiri Utuh', 'kismis-kacang', 'Wonogiri, Jawa Tengah', 'Kacang mete utuh kering besar kualitas super, gurih manis alami, tanpa pecah, diolah higienis tanpa minyak berlebih.', 'premium', 'Grade Super', '/images/mete.webp', 0, array['Kacang Mete Utuh Jumbo Tanpa Pecah', 'Rasa Gurih Manis Alami Renyah', 'Kualitas Premium Kebanggaan Lokal']::text[], 4.92, 88, 12),
('kismis-golden', 'Kismis Manis Golden Jumbo', 'kismis-kacang', 'Iran / Turki', 'Kismis kuning keemasan berbulir montok bersih tanpa biji, dengan perpaduan rasa manis dan sedikit asam segar alami.', 'favorit', 'Kuning Montok', '/images/kismis.webp', 1, array['Bulir Kuning Emas Montok Bersih', 'Tanpa Biji & Bebas Pengawet Berbahaya', 'Kaya Zat Besi & Energi Instan']::text[], 4.85, 198, 13),
('cokelat-truffle-mix', 'Cokelat Truffle Aneka Rasa (Mix)', 'cokelat-gift', 'Turki', 'Cokelat truffle Turki aneka rasa (hazelnut, susu, stroberi, cokelat pekat) dengan isi leleh lembut berbalut foil mewah.', 'best-seller', 'Impor Turki', '/images/truffle.webp', 0, array['Isi Krim Leleh Lumer di Mulut', 'Bungkus Foil Mewah Aneka Warna', 'Paling Disukai Kerabat & Anak-Anak']::text[], 4.9, 183, 14),
('cokelat-kerikil', 'Cokelat Kerikil Fanatik Makkah', 'cokelat-gift', 'Arab Saudi / Turki', 'Cokelat susu berbentuk batu kerikil warna-warni khas Makkah dengan tekstur renyah di luar dan manis lumer di dalam.', 'favorit', 'Ikon Oleh-Oleh', '/images/cokelat.webp', 0, array['Bentuk Unik Mirip Batu Kerikil Warna-Warni', 'Rasa Cokelat Susu Lezat Gurih Manis', 'Camilan Ikonik Wajib Oleh-Oleh Haji']::text[], 4.86, 231, 15),
('gift-3-sekat', 'Gift Mika 3 Sekat Eksklusif', 'cokelat-gift', 'Alfaratha Store', 'Paket mika 3 sekat praktis dan higienis berisi kombinasi Kurma pilihan, Kismis Manis, dan Kacang Pistachio renyah.', 'premium', 'Praktis Mewah', '/images/gift-sekat.webp', 0, array['3 Varian Favorit Dalam 1 Wadah Sekat', 'Kemasan Mika Bening Tebal Elegan', 'Siap Dibagikan Tanpa Repot Mengemas']::text[], 4.9, 76, 16),
('gift-hampers-suvenir', 'Gift Hampers Dus Suvenir Tanpa Zam-Zam', 'cokelat-gift', 'Alfaratha Store', 'Dus suvenir motif Menara Makkah isi Cokelat Truffle, Kismis, Kurma, Kacang Arab & botol kosong siap bagi.', 'best-seller', 'Paket Hemat', '/images/gift-hampers.webp', 0, array['Isi Lengkap Cokelat, Kurma, Kismis, Kacang Arab', 'Dus Menara Makkah Jinjing Cantik', 'Tersedia Eceran Maupun Grosir 100 Pcs']::text[], 4.95, 312, 17),
('zamzam-5l', 'Air Zam-Zam 5 Liter Galon Segel', 'zamzam-herbal', 'Makkah Al-Mukarramah', 'Air Zamzam murni galon kardus 5 liter non-barcode resmi bandara Jeddah, terjamin keaslian dan kemurniannya.', 'best-seller', '100% Asli Makkah', '/images/zamzam.webp', 0, array['Kemasan Galon Kardus Segel Utuh', 'Uji TDS Sesuai Standar Air Zamzam Murni', 'Garansi Keaslian Uang Kembali 100%']::text[], 4.98, 420, 18),
('zamzam-botol-50ml', 'Air Zam-Zam Botol 50 ml Siap Bagi', 'zamzam-herbal', 'Makkah Al-Mukarramah', 'Air Zamzam murni botol mini ukuran 50 ml / 50 cc berlabel kaligrafi rapi dan tutup bersegel, praktis langsung dibagikan.', 'favorit', 'Siap Bagi', '/images/zamzam-botol.webp', 0, array['Sudah Berisi Air Zamzam Murni', 'Tutup Botol Bersegel Rapi Anti Tumpah', 'Praktis Langsung Dimasukkan ke Dus Oleh-Oleh']::text[], 4.9, 165, 19),
('botol-zamzam-kosong', 'Botol Kosong Zam-Zam 60 ml Tutup Segel', 'zamzam-herbal', 'Indonesia', 'Botol plastik bening tebal food-grade ukuran 60 ml dengan tutup ulir bersegel warna hijau untuk isi ulang Zamzam.', 'terbatas', 'Tutup Segel', '/images/botol-kosong.webp', 0, array['Bahan PET Food Grade Bening Tebal', 'Tutup Segel Ulir Rapat Sekali Kunci', 'Hemat untuk Pembagian Zamzam Sendiri']::text[], 4.82, 92, 20),
('madu-kashmir', 'Madu Murni Kashmir Asli 1 Kg', 'zamzam-herbal', 'Lembah Kashmir', 'Madu floral murni dari nektar bunga liar pegunungan Kashmir. Rasa manis kental aromatik alami, expired panjang.', 'premium', '100% Murni', '/images/madu-kashmir.webp', 0, array['Nektar Bunga Liar Dataran Tinggi Kashmir', 'Tekstur Kental Bening Manis Aromatik', 'Kaya Enzim & Antioksidan Alami']::text[], 4.93, 71, 21),
('chia-seed', 'Chia Seed Organik Superfood 500 gr', 'zamzam-herbal', 'Timur Tengah / Meksiko', 'Biji chia seed hitam alami kaya omega-3, kalsium, dan serat tinggi untuk campuran infused water kurma (nabeez) dan madu.', 'favorit', 'Superfood', '/images/chia-seed.webp', 0, array['100% Organik Bersih Bebas Debu', 'Tinggi Asam Lemak Omega-3 & Serat', 'Cocok untuk Menu Sehat Nabeez & Madu']::text[], 4.87, 84, 22),
('garam-himalaya-himsalt', 'Garam Himalaya Murni (Himsalt Refill)', 'zamzam-herbal', 'Pegunungan Himalaya', 'Garam kristal merah muda alami kaya 84 mineral esensial tanpa bahan kimia pemutih, sangat baik untuk diet sehat.', 'terbatas', 'Mineral Alami', '/images/himsalt.webp', 0, array['Garam Kristal Murni Merah Muda Alami', 'Kaya 84 Mineral & Elektrolit Alami', 'Non-Refinasi & Tanpa Anti-Kempal Kimia']::text[], 4.89, 104, 23),
('paket-barokah-box', 'Paket Barokah Siap Bagi', 'paket', 'Alfaratha Store', 'Dus jinjing hemat isi Kurma Khalas, Kismis, Kacang Arab, dan Air Zamzam 80ml.', 'favorit', 'Paket Hemat', '/images/paket-barokah.webp', 0, array['Box jinjing anti penyok', 'Isi 4 item lengkap', 'Siap distribusi jamaah']::text[], 4.9, 214, 24),
('paket-madinah-box', 'Paket Madinah Box Eksklusif', 'paket', 'Alfaratha Store', 'Hardbox tenteng foil emas isi Kurma Sukkari/Ajwa, Kismis, Pistachio, Cokelat & Zamzam 80ml.', 'best-seller', 'Favorit Jamaah', '/images/gift-hampers.webp', 0, array['Gratis Custom Kartu Nama', 'Isi 5 item favorit', 'Garansi kemasan aman']::text[], 4.96, 389, 25)
